import boto3

def run_ocr(document):
    textract = boto3.client('textract')
    response = textract.detect_document_text(
        Document={'Bytes': document}
    )
    text = ''
    for item in response['Blocks']:
        if item['BlockType'] == 'LINE':
            text += item['Text'] + ' '
    return text

from typing import Any, Dict, List

class LocalStorageRequest:
    def __init__(self, bucket_name: str, object_key: str, data: bytes):
        self.bucket_name = bucket_name
        self.object_key = object_key
        self.data = data

class LocalStorageResponse:
    def __init__(self, status_code: int, message: str):
        self.status_code = status_code
        self.message = message

def normalize_storage_response(response: LocalStorageResponse) -> Dict[str, Any]:
    return {
        'status_code': response.status_code,
        'message': response.message
    }

def normalize_storage_request(request: LocalStorageRequest) -> Dict[str, Any]:
    return {
        'bucket_name': request.bucket_name,
        'object_key': request.object_key,
        'data': request.data
    }

import boto3

def configure_s3_client():
    return boto3.client('s3')

def upload_to_s3(bucket_name, file_path, object_name=None):
    if object_name is None:
        object_name = file_path
    s3_client = configure_s3_client()
    try:
        response = s3_client.upload_file(file_path, bucket_name, object_name)
        print(f'File uploaded successfully to {bucket_name}/{object_name}')
    except Exception as e:
        print(e)

def download_from_s3(bucket_name, object_name, file_path):
    s3_client = configure_s3_client()
    try:
        response = s3_client.download_file(bucket_name, object_name, file_path)
        print(f'File downloaded successfully from {bucket_name}/{object_name}')
    except Exception as e:
        print(e)

import boto3

def list_prefix(bucket_name, prefix):
    s3 = boto3.client('s3')
    response = s3.list_objects_v2(Bucket=bucket_name, Prefix=prefix)
    if 'Contents' in response:
        for obj in response['Contents']:
            print(obj['Key'])
    else:
        print('No objects found with the specified prefix.')

# Example usage:
# list_prefix('my-bucket', 'my-prefix')

